pub struct SecretToken(String);

impl SecretToken {
    pub fn parse(encoded: impl Into<String>) -> Option<Self> {
        let encoded = encoded.into();
        URL_SAFE_NO_PAD
            .decode(&encoded)
            .ok()
            .filter(|bytes| bytes.len() == TOKEN_BYTES)
            .map(|_| Self(encoded))
    }

    pub fn expose(&self) -> &str {
        &self.0
    }
}

